-- Classic gear for JournalGearBIS, generated from the realm's world database (AzerothCore with
-- mod-individual-progression's Classic item and loot changes). Don't edit by hand: Curated.lua and Profiles.lua
-- are the files to change.
--
--   instances[key] = { name, raid, players, stage (progression stage that opens it), level, map }
--   items[id] = { name, inventory type, class*100+subclass, item level, required level, quality,
--                 classes (bit mask of classes that can use it), races (bit mask, 0 = all), unique,
--                 stats = { ... }, sources = { ... } }
--   a source:  { "D", instance, chance (all its bosses together), "who" }   a drop
--              { "C", instance, chance, "chest" }                         a chest
--              { "Q", quest, "title", raid it needs or 0, stage, races, quest level }
--              { "V", "vendor", price in copper, faction, standing, stage }
--              { "X", "how it's made" }

